INSERT INTO kanji_decks (user_id, title, description, visibility, is_system, jlpt_level, total_kanji, is_active, is_deleted, version, created_at, updated_at) SELECT NULL, 'JLPT N5 (built-in)', N'79 Hán tự cơ bản trình độ N5.', 'PUBLIC', b'1', 'N5', (SELECT COUNT(*) FROM kanji_details WHERE jlpt_level = 'N5'), b'1', b'0', 0, NOW(6), NOW(6) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM kanji_decks WHERE title = 'JLPT N5 (built-in)' AND is_system = b'1');
INSERT IGNORE INTO kanji_deck_items (deck_id, kanji_id, order_index, is_active, is_deleted, version, created_at, updated_at) SELECT d.id, k.id, ROW_NUMBER() OVER (ORDER BY k.id) - 1, b'1', b'0', 0, NOW(6), NOW(6) FROM kanji_details k CROSS JOIN (SELECT id FROM kanji_decks WHERE title = 'JLPT N5 (built-in)' AND is_system = b'1' LIMIT 1) d WHERE k.jlpt_level = 'N5';
